L2_1 = "\235\130\152\235\138\148 \235\139\164\235\165\184 \235\134\136\235\147\164\236\157\180\235\158\145 \235\139\172\235\157\188. \236\158\132\235\172\180\235\165\188 \236\134\141\236\152\128\235\139\164\234\179\160 \237\149\180\236\132\156 \235\132\136\237\157\172\235\165\188 \234\179\160\236\134\140\237\149\152\234\177\176\235\130\152 \234\183\184\235\159\180 \236\131\157\234\176\129\236\157\128 \236\160\132\237\152\128 \236\151\134\236\150\180."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "\228\191\186\227\129\175\228\187\150\227\129\174\227\130\132\227\129\164\227\130\137\227\129\168\227\129\175\233\129\149\227\129\134\227\128\130\233\168\153\227\129\151\227\129\159\227\129\139\227\130\137\227\129\168\232\168\128\227\129\163\227\129\166\227\128\129\232\168\180\227\129\136\227\130\139\227\129\164\227\130\130\227\130\138\227\129\175\227\129\170\227\129\132\227\128\130"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I\226\128\153m not like the other guys. I\226\128\153m not going to sue you or anything just because you lied about the mission."
L1_1.m_Talk_ENG = L2_1
L2_1 = "\230\136\145\229\146\140\229\133\182\228\187\150\228\186\186\228\184\141\228\184\128\230\168\163\227\128\130\230\136\145\228\184\141\230\156\131\229\155\160\231\130\186\228\189\160\229\156\168\228\187\187\229\139\153\228\184\173\230\172\186\233\168\153\228\186\134\230\136\145\229\128\145\229\176\177\230\142\167\229\145\138\228\189\160\227\128\130"
L1_1.m_Talk_TWN = L2_1
L2_1 = "\224\184\156\224\184\161\224\185\132\224\184\161\224\185\136\224\185\128\224\184\171\224\184\161\224\184\183\224\184\173\224\184\153\224\184\132\224\184\153\224\184\173\224\184\183\224\185\136\224\184\153\224\184\171\224\184\163\224\184\173\224\184\129\224\184\153\224\184\176 \224\184\156\224\184\161\224\184\136\224\184\176\224\185\132\224\184\161\224\185\136\224\184\159\224\185\137\224\184\173\224\184\135\224\184\132\224\184\184\224\184\147\224\184\171\224\184\163\224\184\183\224\184\173\224\184\171\224\184\178\224\185\128\224\184\163\224\184\183\224\185\136\224\184\173\224\184\135\224\184\163\224\185\137\224\184\173\224\184\135\224\185\128\224\184\163\224\184\181\224\184\162\224\184\153\224\184\173\224\184\176\224\185\132\224\184\163\224\184\158\224\184\167\224\184\129\224\184\153\224\184\177\224\185\137\224\184\153 \224\185\129\224\184\132\224\185\136\224\185\128\224\184\158\224\184\163\224\184\178\224\184\176\224\184\132\224\184\184\224\184\147\224\185\130\224\184\129\224\184\171\224\184\129\224\185\128\224\184\163\224\184\183\224\185\136\224\184\173\224\184\135\224\184\160\224\184\178\224\184\163\224\184\129\224\184\180\224\184\136"
