L1_1.m_Talk_VTN = L2_1
L2_1 = "\230\136\145\229\146\140\229\133\182\228\187\150\228\186\186\228\184\141\228\184\128\230\160\183\227\128\130 \230\136\145\228\184\141\228\188\154\229\155\160\228\184\186\228\189\160\233\154\144\231\158\146\228\186\134\228\187\187\229\138\161\232\175\166\230\131\133\232\128\140\230\142\167\229\145\138\228\189\160\228\187\172\227\128\130"
